/* 計算クエスト 手書き数字の読み取り（端末の中だけで動く。通信なし）
   モデル：小さなCNN（たたみこみ2層＋全結合2層）。MNIST の手書き数字で学習し、重みを8ビットにして下に埋めこみ */
(function(){
var W='';
var SC={"w1": 0.011696972884237766, "b1": 0.0032732656691223383, "w2": 0.007959093898534775, "b2": 0.003183382796123624, "w3": 0.007906170561909676, "b3": 0.0024650997947901487, "w4": 0.004142404533922672, "b4": 0.0015451424987986684};
var P=null;
function load(){if(P)return P;var bin=atob(W),n=bin.length,i8=new Int8Array(n);for(var i=0;i<n;i++){var c=bin.charCodeAt(i);i8[i]=c>127?c-256:c;}
  var sizes=[['w1',144],['b1',16],['w2',4608],['b2',32],['w3',51200],['b3',64],['w4',640],['b4',10]],o=0;P={};
  sizes.forEach(function(s){var a=new Float32Array(s[1]),k=SC[s[0]];for(var j=0;j<s[1];j++)a[j]=i8[o+j]*k;P[s[0]]=a;o+=s[1];});return P;}
/* x: Float32Array(H*W*C) HWC。w: kh,kw,ci,co（HWIO） */
function conv(x,H,Wd,C,w,b,CO){var OH=H-2,OW=Wd-2,y=new Float32Array(OH*OW*CO);
  for(var oy=0;oy<OH;oy++)for(var ox=0;ox<OW;ox++){var base=(oy*OW+ox)*CO;for(var co=0;co<CO;co++)y[base+co]=b[co];
    for(var ky=0;ky<3;ky++)for(var kx=0;kx<3;kx++){var xi=((oy+ky)*Wd+(ox+kx))*C,wi=(ky*3+kx)*C*CO;
      for(var ci=0;ci<C;ci++){var v=x[xi+ci];if(v===0)continue;var wr=wi+ci*CO;for(var co2=0;co2<CO;co2++)y[base+co2]+=v*w[wr+co2];}}
    for(var c3=0;c3<CO;c3++)if(y[base+c3]<0)y[base+c3]=0;}
  return y;}
function pool(x,H,Wd,C){var OH=H>>1,OW=Wd>>1,y=new Float32Array(OH*OW*C);
  for(var oy=0;oy<OH;oy++)for(var ox=0;ox<OW;ox++)for(var c=0;c<C;c++){var m=-1e9;
    for(var dy=0;dy<2;dy++)for(var dx=0;dx<2;dx++){var v=x[((oy*2+dy)*Wd+(ox*2+dx))*C+c];if(v>m)m=v;}y[(oy*OW+ox)*C+c]=m;}return y;}
function dense(x,w,b,N,M,relu){var y=new Float32Array(M);for(var j=0;j<M;j++)y[j]=b[j];
  for(var i=0;i<N;i++){var v=x[i];if(v===0)continue;var r=i*M;for(var j2=0;j2<M;j2++)y[j2]+=v*w[r+j2];}
  if(relu)for(var k=0;k<M;k++)if(y[k]<0)y[k]=0;return y;}
function classify(img){var p=load();
  var a=pool(conv(img,28,28,1,p.w1,p.b1,16),26,26,16);
  var c=pool(conv(a,13,13,16,p.w2,p.b2,32),11,11,32);
  var h=dense(c,p.w3,p.b3,800,64,true),o=dense(h,p.w4,p.b4,64,10,false);
  var mx=-1e9,i;for(i=0;i<10;i++)if(o[i]>mx)mx=o[i];var s=0,pr=[];for(i=0;i<10;i++){pr[i]=Math.exp(o[i]-mx);s+=pr[i];}
  var best=0;for(i=0;i<10;i++){pr[i]/=s;if(pr[i]>pr[best])best=i;}
  return {d:best,p:pr[best],probs:pr};}

/* 線のまとまり → 28×28（MNIST と同じ形：20×20 の枠に合わせて、重心を中心に） */
var cv=null;
function rasterize(strokes){
  var x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;strokes.forEach(function(s){s.forEach(function(p){if(p[0]<x0)x0=p[0];if(p[0]>x1)x1=p[0];if(p[1]<y0)y0=p[1];if(p[1]>y1)y1=p[1];});});
  var w=x1-x0,h=y1-y0,S=112,LW=10,sz=Math.max(w,h,1),k=(80-LW)/sz;
  if(!cv){cv=document.createElement('canvas');cv.width=S;cv.height=S;}
  var g=cv.getContext('2d',{willReadFrequently:true});g.setTransform(1,0,0,1,0,0);g.fillStyle='#000';g.fillRect(0,0,S,S);
  g.strokeStyle='#fff';g.fillStyle='#fff';g.lineWidth=LW;g.lineCap='round';g.lineJoin='round';
  var ox=(S-w*k)/2,oy=(S-h*k)/2;
  strokes.forEach(function(s){g.beginPath();s.forEach(function(p,i){var X=ox+(p[0]-x0)*k,Y=oy+(p[1]-y0)*k;if(i)g.lineTo(X,Y);else g.moveTo(X,Y);});
    if(s.length===1){g.arc(ox+(s[0][0]-x0)*k,oy+(s[0][1]-y0)*k,LW/2,0,7);g.fill();}else g.stroke();});
  var d=g.getImageData(0,0,S,S).data,sm=new Float32Array(784),mx=0,i,j,yy,xx;
  for(i=0;i<28;i++)for(j=0;j<28;j++){var t=0;for(yy=0;yy<4;yy++)for(xx=0;xx<4;xx++)t+=d[((i*4+yy)*S+(j*4+xx))*4];t/=16*255;sm[i*28+j]=t;if(t>mx)mx=t;}
  var my=0,mxx=0,m=0;for(i=0;i<784;i++){sm[i]/=(mx||1);m+=sm[i];my+=sm[i]*((i/28)|0);mxx+=sm[i]*(i%28);}
  if(!m)return sm;var cy=my/m,cx=mxx/m,dy=14-cy,dx=14-cx,out=new Float32Array(784);
  /* 重心を (14,14) へ（線形補間） */
  for(i=0;i<28;i++)for(j=0;j<28;j++){var sy=i-dy,sx=j-dx,iy=Math.floor(sy),ix=Math.floor(sx),fy=sy-iy,fx=sx-ix,v=0;
    function at(a,b){return (a>=0&&a<28&&b>=0&&b<28)?sm[a*28+b]:0;}
    v=at(iy,ix)*(1-fy)*(1-fx)+at(iy,ix+1)*(1-fy)*fx+at(iy+1,ix)*fy*(1-fx)+at(iy+1,ix+1)*fy*fx;out[i*28+j]=v;}
  return out;}

/* 線を「1字ずつ」に分ける：横の範囲が重なる線は同じ字 */
function bb(s){var a=[1e9,1e9,-1e9,-1e9];s.forEach(function(p){if(p[0]<a[0])a[0]=p[0];if(p[1]<a[1])a[1]=p[1];if(p[0]>a[2])a[2]=p[0];if(p[1]>a[3])a[3]=p[1];});return a;}
function xr(b,m){var w=b[2]-b[0];if(w>=m)return [b[0],b[2]];var c=(b[0]+b[2])/2;return [c-m/2,c+m/2];}
function segment(strokes,padH){
  var G=strokes.filter(function(s){return s.length;}).map(function(s){return {s:[s],b:bb(s)};});
  var minW=Math.max(6,padH*0.06),changed=true;
  while(changed){changed=false;
    for(var i=0;i<G.length&&!changed;i++)for(var j=i+1;j<G.length&&!changed;j++){var a=G[i].b,b=G[j].b;
      /* 細い線（1 や 4 のたて線）は、はばを minW として考える */
      var ea=xr(a,minW),eb=xr(b,minW),ov=Math.min(ea[1],eb[1])-Math.max(ea[0],eb[0]),nw=Math.min(ea[1]-ea[0],eb[1]-eb[0]);
      var ca=(a[0]+a[2])/2,cb=(b[0]+b[2])/2,inside=(cb>a[0]&&cb<a[2]&&(b[2]-b[0])<(a[2]-a[0]))||(ca>b[0]&&ca<b[2]&&(a[2]-a[0])<(b[2]-b[0]));
      if(ov>0.3*nw||inside){
        G[i]={s:G[i].s.concat(G[j].s),b:[Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[2],b[2]),Math.max(a[3],b[3])]};G.splice(j,1);changed=true;}}}
  /* 小さすぎるもの（点・ゴミ）はいちばん近い字にくっつける */
  var H=0;G.forEach(function(g){H=Math.max(H,g.b[3]-g.b[1]);});
  var big=G.filter(function(g){return Math.max(g.b[2]-g.b[0],g.b[3]-g.b[1])>=Math.max(8,H*0.22);});
  G.forEach(function(g){if(big.indexOf(g)>=0||!big.length)return;var cx=(g.b[0]+g.b[2])/2,best=null,bd=1e9;
    big.forEach(function(q){var d=Math.abs((q.b[0]+q.b[2])/2-cx);if(d<bd){bd=d;best=q;}});
    if(best&&bd<H*0.6){best.s=best.s.concat(g.s);best.b=[Math.min(best.b[0],g.b[0]),Math.min(best.b[1],g.b[1]),Math.max(best.b[2],g.b[2]),Math.max(best.b[3],g.b[3])];}});
  big=big.length?big:G;
  big.sort(function(a,b){return a.b[0]-b.b[0];});return big;}

window.KHW={classify:classify,rasterize:rasterize,segment:segment,
  read:function(strokes,padH){return segment(strokes,padH).map(function(g){var r=classify(rasterize(g.s));r.b=g.b;r.s=g.s;return r;});}};
})();
